SELECT id, type_id, name
FROM figure_subtype
WHERE user_id = #{userId} AND id = #{id}

SELECT id, type_id, name
FROM figure_subtype
WHERE user_id = #{userId} AND type_id = #{parentId} AND name = #{name}

SELECT COUNT(*)
FROM figure_subtype
WHERE user_id = #{userId} AND type_id = #{parentId}

SELECT COUNT(DISTINCT id)
FROM figure
WHERE user_id = #{userId} AND subtype_id = #{id}
